INSERT INTO public.reception_quiz (mavzu, test_id, question_text, option_text, option_image, is_correct) VALUES ('3-mavzu', '1-test', 'Mehmon reseptionga murojaat qilganda xodimning nutqi qanday bo‘lishi kerak?', 'C) Norasmiy va erkin', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-1-c.png', false),('3-mavzu', '1-test', 'Mehmon reseptionga murojaat qilganda xodimning nutqi qanday bo‘lishi kerak?', 'D) Buyruq ohangida va tartibli', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-1-d.png', false),('3-mavzu', '2-test', 'Quyidagi holatlardan qaysi biri nutq madaniyatiga zid hisoblanadi?', 'A) Muloyim ohangda gapirish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-2-a.png', false),('3-mavzu', '2-test', 'Quyidagi holatlardan qaysi biri nutq madaniyatiga zid hisoblanadi?', 'B) Mehmon gapini bo‘lmasdan eshitish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-2-b.png', false),('3-mavzu', '2-test', 'Quyidagi holatlardan qaysi biri nutq madaniyatiga zid hisoblanadi?', 'C) Mehmon savoliga tezlik bilan va keskin javob berish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-2-c.png', true),('3-mavzu', '2-test', 'Quyidagi holatlardan qaysi biri nutq madaniyatiga zid hisoblanadi?', 'D) Aniq va tushunarli iboralar ishlatish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-2-d.png', false),('3-mavzu', '3-test', 'Mehmon bir savolni bir necha bor takrorladi. Bu holatda reseption xodimi qanday yo‘l tutishi kerak?', 'A) Noroziligini bildirib qo‘yishi kerak', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-3-a.png', false),('3-mavzu', '3-test', 'Mehmon bir savolni bir necha bor takrorladi. Bu holatda reseption xodimi qanday yo‘l tutishi kerak?', 'B) Mehmonni shoshirish va masalani hal etishi kerak', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/Turizm-3/3-3-b.png', false),('3-mavzu', '3-test', 'Mehmon bir savolni bir necha bor takrorladi. Bu holatda reseption xod